const FatawaListPage = ({t,navigate,fatwas,shaykhs,filterTopic,setFilterTopic,filterShaykh,setFilterShaykh,searchQuery,setSearchQuery,loading}) => (
  <div style={{paddingTop:'68px',minHeight:'100vh'}}>
    <section style={{background:t.alt,padding:'52px 48px',borderBottom:`1px solid ${t.border}`}}>
      <div style={{maxWidth:'1100px',margin:'0 auto'}}>
        <div style={{fontSize:'11px',letterSpacing:'4px',color:t.accent,textTransform:'uppercase',
          fontFamily:"'Hind Siliguri',sans-serif",fontWeight:700,marginBottom:'10px'}}>✦ আর্কাইভ ✦</div>
        <h1 style={{fontFamily:"'Cormorant Garamond',serif",fontSize:'48px',fontWeight:700,color:t.text,marginBottom:'28px'}}>ফতওয়া সমূহ</h1>
        <div style={{position:'relative',maxWidth:'480px',marginBottom:'24px'}}>
          <input type="text" placeholder="ফতওয়া খুঁজুন..." value={searchQuery}
            onChange={e=>setSearchQuery(e.target.value)}
            style={{width:'100%',padding:'13px 46px 13px 18px',fontSize:'15px',fontFamily:"'Hind Siliguri',sans-serif",
              background:t.card,border:`2px solid ${t.border}`,borderRadius:'8px',color:t.text,outline:'none',boxSizing:'border-box'}}/>
          <span style={{position:'absolute',right:'16px',top:'50%',transform:'translateY(-50%)',color:t.muted,fontSize:'18px'}}>⌕</span>
        </div>
        <div style={{display:'flex',gap:'8px',flexWrap:'wrap',marginBottom:'10px'}}>
          <Tag label="সব বিষয়" t={t} active={filterTopic==='সব'} onClick={()=>setFilterTopic('সব')}/>
          {TOPICS.map(tp=><Tag key={tp} label={tp} t={t} active={filterTopic===tp} onClick={()=>setFilterTopic(tp)}/>)}
        </div>
        <div style={{display:'flex',gap:'8px',flexWrap:'wrap'}}>
          <Tag label="সব শায়খ" t={t} active={filterShaykh==='সব'} onClick={()=>setFilterShaykh('সব')}/>
          {shaykhs.map(s=><Tag key={s.id} label={s.name.replace('শায়খ ','')} t={t} active={filterShaykh===String(s.id)} onClick={()=>setFilterShaykh(String(s.id))}/>)}
        </div>
      </div>
    </section>
    <div style={{padding:'48px',maxWidth:'1100px',margin:'0 auto'}}>
      {loading?<Loading t={t}/>:fatwas.length===0
        ?<div style={{textAlign:'center',padding:'80px',color:t.muted,fontFamily:"'Hind Siliguri',sans-serif",fontSize:'16px'}}>কোনো ফতওয়া পাওয়া যায়নি।</div>
        :<div style={{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:'24px'}}>
          {fatwas.map(f=><FatwaCard key={f.id} f={f} t={t} shaykhs={shaykhs} navigate={navigate}/>)}
        </div>
      }
    </div>
  </div>
);

const FatawaDetailPage = ({t,navigate,fatwa,shaykhs}) => {
  const [tab,setTab] = useState('text');
  if(!fatwa) return <div style={{paddingTop:'120px',textAlign:'center',color:t.muted,fontFamily:"'Hind Siliguri',sans-serif"}}>ফতওয়া পাওয়া যায়নি।</div>;
  const sh = shaykhs.find(s=>s.id===fatwa.shaykhId);
  const tabs = ['text',fatwa.hasPdf&&'pdf',fatwa.hasVideo&&'video'].filter(Boolean);
  return (
    <div style={{paddingTop:'68px',minHeight:'100vh'}}>
      <div style={{padding:'14px 48px',background:t.alt,borderBottom:`1px solid ${t.border}`}}>
        <div style={{maxWidth:'900px',margin:'0 auto',display:'flex',gap:'8px',fontSize:'13px',color:t.muted,fontFamily:"'Hind Siliguri',sans-serif",alignItems:'center'}}>
          <span className="nav-link" onClick={()=>navigate('home')} style={{cursor:'pointer'}}>হোম</span>
          <span style={{color:t.border}}>›</span>
          <span className="nav-link" onClick={()=>navigate('fatwas')} style={{cursor:'pointer'}}>ফতওয়া</span>
          <span style={{color:t.border}}>›</span>
          <span style={{color:t.accent}}>{fatwa.title}</span>
        </div>
      </div>
      <div style={{maxWidth:'900px',margin:'0 auto',padding:'56px 48px'}}>
        <div style={{display:'flex',gap:'8px',marginBottom:'20px',flexWrap:'wrap'}}>
          <Tag label={fatwa.topic} t={t}/>
          {fatwa.hasPdf&&<Tag label="PDF উপলব্ধ" t={t}/>}
          {fatwa.hasVideo&&<Tag label="ভিডিও উপলব্ধ" t={t}/>}
        </div>
        <h1 style={{fontFamily:"'Cormorant Garamond',serif",fontSize:'44px',fontWeight:700,color:t.text,lineHeight:1.2,marginBottom:'32px'}}>{fatwa.title}</h1>
        <div style={{display:'flex',alignItems:'center',gap:'16px',padding:'20px 24px',background:t.alt,
          borderRadius:'12px',border:`1px solid ${t.border}`,marginBottom:'44px'}}>
          <Avatar name={sh?.name||''} t={t} size={52}/>
          <div style={{flex:1}}>
            <div style={{fontFamily:"'Hind Siliguri',sans-serif",fontWeight:700,color:t.text,fontSize:'16px'}}>{sh?.name}</div>
            <div style={{fontSize:'13px',color:t.accent,fontFamily:"'Hind Siliguri',sans-serif",marginTop:'3px'}}>{sh?.specialty} · {fatwa.date}</div>
          </div>
          <div style={{fontSize:'13px',color:t.muted,fontFamily:"'Hind Siliguri',sans-serif"}}>👁 {fatwa.views} বার পড়া হয়েছে</div>
        </div>
        {tabs.length>1&&(
          <div style={{display:'flex',gap:'4px',marginBottom:'32px',background:t.alt,padding:'4px',borderRadius:'8px',width:'fit-content'}}>
            {tabs.map(tb=>(
              <button key={tb} onClick={()=>setTab(tb)} style={{padding:'10px 22px',borderRadius:'6px',border:'none',cursor:'pointer',
                fontFamily:"'Hind Siliguri',sans-serif",fontSize:'14px',fontWeight:500,
                background:tab===tb?t.accent:'transparent',color:tab===tb?'#fff':t.muted,transition:'all 0.2s'}}>
                {tb==='text'?'📝 পাঠ্য':tb==='pdf'?'📄 পিডিএফ':'🎥 ভিডিও'}
              </button>
            ))}
          </div>
        )}
        {tab==='text'&&(
          <div>
            <div style={{background:t.accentFade,borderLeft:`4px solid ${t.accent}`,borderRadius:'0 10px 10px 0',
              padding:'24px 28px',marginBottom:'36px'}}>
              <div style={{fontSize:'11px',letterSpacing:'3px',color:t.accent,textTransform:'uppercase',
                fontFamily:"'Hind Siliguri',sans-serif",fontWeight:700,marginBottom:'12px'}}>প্রশ্ন</div>
              <p style={{fontFamily:"'Hind Siliguri',sans-serif",fontSize:'18px',fontWeight:600,color:t.text,lineHeight:1.75,margin:0}}>{fatwa.question}</p>
            </div>
            <div style={{fontSize:'11px',letterSpacing:'3px',color:t.accent,textTransform:'uppercase',
              fontFamily:"'Hind Siliguri',sans-serif",fontWeight:700,marginBottom:'16px'}}>উত্তর</div>
            <p style={{fontFamily:"'Hind Siliguri',sans-serif",fontSize:'17px',color:t.text,lineHeight:2,margin:0}}>{fatwa.answer}</p>
          </div>
        )}
        {tab==='pdf'&&fatwa.pdfUrl&&(
          <div style={{border:`1px solid ${t.border}`,borderRadius:'12px',overflow:'hidden'}}>
            <iframe src={fatwa.pdfUrl} style={{width:'100%',height:'600px',border:'none'}} title="PDF Viewer"/>
          </div>
        )}
        {tab==='video'&&fatwa.videoUrl&&(
          <div style={{border:`1px solid ${t.border}`,borderRadius:'12px',overflow:'hidden'}}>
            <iframe src={fatwa.videoUrl} style={{width:'100%',height:'460px',border:'none'}} title="Video Player" allowFullScreen/>
          </div>
        )}
        <div style={{marginTop:'48px',paddingTop:'28px',borderTop:`1px solid ${t.border}`,display:'flex',gap:'12px',alignItems:'center',flexWrap:'wrap'}}>
          <span style={{fontFamily:"'Hind Siliguri',sans-serif",fontSize:'14px',color:t.muted,fontWeight:600}}>শেয়ার করুন:</span>
          {['Facebook','WhatsApp','Telegram','Twitter'].map(p=>(
            <button key={p} style={{padding:'8px 16px',border:`1px solid ${t.border}`,borderRadius:'6px',
              background:'transparent',cursor:'pointer',fontFamily:"'Hind Siliguri',sans-serif",
              fontSize:'13px',color:t.text,transition:'all 0.2s'}}>{p}</button>
          ))}
        </div>
      </div>
    </div>
  );
};

